    ordered = sorted(events, key=lambda e: e['seq'])

    seen_id = {}        # id -> full event snapshot (for retry/dedup detection)
    seq_owner = {}      # seq -> id (to detect duplicate seq across distinct events)
    settled = {}        # id -> {'cents', 'kind', 'account'} for credit/debit events
    reversed_ids = set()
    total = 0

    for e in ordered:
        eid = e['id']
        seq = e['seq']
        kind = e['kind']

        if kind not in ('credit', 'debit', 'reverse'):
            raise ValueError('unknown kind')

        # Validate cents for credit/debit (reversal carries no cents).
        if kind in ('credit', 'debit'):
            c = e['cents']
            if isinstance(c, bool) or not isinstance(c, int) or c < 0:
                raise ValueError('invalid cents')

