        snapshot = dict(e)
        if eid in seen_id:
            if seen_id[eid] != snapshot:
                raise ValueError('reused id with different content')
            continue
        seen_id[eid] = snapshot

        if seq in seq_owner:
            raise ValueError('duplicate seq')
        seq_owner[seq] = eid

        acct = e['account']

        if kind in ('credit', 'debit'):
            settled[eid] = {'cents': c, 'kind': kind, 'account': acct}
            if acct == account:
                total += c if kind == 'credit' else -c
        else:
            target = settled.get(e['target'])
            if target is None or e['target'] in reversed_ids:
                raise ValueError('invalid reversal target')
            if acct != target['account']:
                raise ValueError('reversal in another account')
            reversed_ids.add(e['target'])
            if acct == account:
                effect = target['cents'] if target['kind'] == 'credit' else -target['cents']
                total -= effect

    return total

