import unittest

from ledger import balance


def credit(i, seq, acct, cents):
    return {'id': i, 'seq': seq, 'account': acct, 'kind': 'credit', 'cents': cents}


def debit(i, seq, acct, cents):
    return {'id': i, 'seq': seq, 'account': acct, 'kind': 'debit', 'cents': cents}


def reverse(i, seq, acct, target):
    return {'id': i, 'seq': seq, 'account': acct, 'kind': 'reverse', 'target': target}


class TestNormalBehavior(unittest.TestCase):
    def test_empty_returns_zero(self):
        self.assertEqual(balance([], 'a'), 0)

    def test_credit_debit_net(self):
        events = [
            credit('c1', 1, 'a', 100),
            debit('d1', 2, 'a', 30),
            credit('c2', 3, 'a', 20),
        ]
        self.assertEqual(balance(events, 'a'), 90)

    def test_ignores_other_accounts(self):
        events = [
            credit('c1', 1, 'a', 100),
            credit('c2', 2, 'b', 500),
        ]
        self.assertEqual(balance(events, 'a'), 100)

    def test_unsorted_input_processed_by_seq(self):
        events = [
            credit('c1', 3, 'a', 100),
            debit('d1', 1, 'a', 30),
            credit('c2', 2, 'a', 20),
        ]
        self.assertEqual(balance(events, 'a'), 90)

    def test_exact_duplicate_counts_once(self):
        ev = credit('c1', 1, 'a', 100)
        events = [ev, dict(ev)]
        self.assertEqual(balance(events, 'a'), 100)

    def test_reverse_cancels_credit(self):
        events = [
            credit('c1', 1, 'a', 100),
            reverse('r1', 2, 'a', 'c1'),
        ]
        self.assertEqual(balance(events, 'a'), 0)

    def test_reverse_cancels_debit(self):
        events = [
            debit('d1', 1, 'a', 50),
            reverse('r1', 2, 'a', 'd1'),
        ]
        self.assertEqual(balance(events, 'a'), 0)

    def test_reverse_ignored_when_other_account(self):
        events = [
            credit('c1', 1, 'b', 100),
            reverse('r1', 2, 'b', 'c1'),
        ]
        self.assertEqual(balance(events, 'a'), 0)

    def test_does_not_mutate_input(self):
        events = [
            credit('c1', 3, 'a', 100),
            debit('d1', 1, 'a', 30),
        ]
        before = [dict(e) for e in events]
        balance(events, 'a')
        self.assertEqual(events, before)


class TestDefects(unittest.TestCase):
    def test_reused_id_different_content_raises(self):
        events = [
            credit('c1', 1, 'a', 100),
            credit('c1', 2, 'a', 100),
        ]
        with self.assertRaises(ValueError):
            balance(events, 'a')

    def test_reused_id_other_account_raises(self):
        events = [
            credit('c1', 1, 'a', 100),
            credit('c1', 2, 'b', 100),
        ]
        with self.assertRaises(ValueError):
            balance(events, 'a')

    def test_unknown_kind_raises(self):
        events = [{'id': 'x', 'seq': 1, 'account': 'a', 'kind': 'bogus', 'cents': 1}]
        with self.assertRaises(ValueError):
            balance(events, 'a')

    def test_negative_cents_raises(self):
        events = [credit('c1', 1, 'a', -5)]
        with self.assertRaises(ValueError):
            balance(events, 'a')

    def test_noninteger_cents_raises(self):
        events = [credit('c1', 1, 'a', 5.0)]
        with self.assertRaises(ValueError):
            balance(events, 'a')

    def test_boolean_cents_raises(self):
        events = [credit('c1', 1, 'a', True)]
        with self.assertRaises(ValueError):
            balance(events, 'a')

    def test_duplicate_seq_distinct_events_raises(self):
        events = [
            credit('c1', 1, 'a', 100),
            debit('d1', 1, 'a', 30),
        ]
        with self.assertRaises(ValueError):
            balance(events, 'a')

    def test_reverse_missing_target_raises(self):
        events = [reverse('r1', 1, 'a', 'nope')]
        with self.assertRaises(ValueError):
            balance(events, 'a')

    def test_reverse_later_target_raises(self):
        events = [
            reverse('r1', 1, 'a', 'c1'),
            credit('c1', 2, 'a', 100),
        ]
        with self.assertRaises(ValueError):
            balance(events, 'a')

    def test_reverse_of_reverse_raises(self):
        events = [
            credit('c1', 1, 'a', 100),
            reverse('r1', 2, 'a', 'c1'),
            reverse('r2', 3, 'a', 'r1'),
        ]
        with self.assertRaises(ValueError):
            balance(events, 'a')

    def test_reverse_other_account_raises(self):
        events = [
            credit('c1', 1, 'a', 100),
            reverse('r1', 2, 'b', 'c1'),
        ]
        with self.assertRaises(ValueError):
            balance(events, 'a')

    def test_reverse_already_reversed_raises(self):
        events = [
            credit('c1', 1, 'a', 100),
            reverse('r1', 2, 'a', 'c1'),
            reverse('r2', 3, 'a', 'c1'),
        ]
        with self.assertRaises(ValueError):
            balance(events, 'a')

    def test_invalid_event_in_other_account_still_raises(self):
        events = [
            credit('ok', 1, 'a', 100),
            credit('bad', 2, 'b', -1),
        ]
        with self.assertRaises(ValueError):
            balance(events, 'a')


if __name__ == '__main__':
    unittest.main()

