import unittest

from ledger import balance


def credit(i, seq, acct, cents):
    return {'id': i, 'seq': seq, 'account': acct, 'kind': 'credit', 'cents': cents}


def debit(i, seq, acct, cents):
    return {'id': i, 'seq': seq, 'account': acct, 'kind': 'debit', 'cents': cents}


def reverse(i, seq, acct, target):
    return {'id': i, 'seq': seq, 'account': acct, 'kind': 'reverse', 'target': target}


class TestNormalBehavior(unittest.TestCase):
    def test_empty_returns_zero(self):
        self.assertEqual(balance([], 'a'), 0)

    def test_credit_debit_net(self):
        events = [
            credit('c1', 1, 'a', 100),
            debit('d1', 2, 'a', 30),
            credit('c2', 3, 'a', 20),
        ]
        self.assertEqual(balance(events, 'a'), 90)

    def test_ignores_other_accounts(self):
        events = [
            credit('c1', 1, 'a', 100),
            credit('c2', 2, 'b', 500),
        ]
        self.assertEqual(balance(events, 'a'), 100)

    def test_unsorted_input_processed_by_seq(self):
        events = [
            credit('c1', 3, 'a', 100),
            debit('d1', 1, 'a', 30),
            credit('c2', 2, 'a', 20),
        ]
        self.assertEqual(balance(events, 'a'), 90)

    def test_exact_duplicate_counts_once(self):
        ev = credit('c1', 1, 'a', 100)
        events = [ev, dict(ev)]
        self.assertEqual(balance(events, 'a'), 100)

    def test_reverse_cancels_credit(self):
        events = [
            credit('c1', 1, 'a', 100),
            reverse('r1', 2, 'a', 'c1'),
        ]
        self.assertEqual(balance(events, 'a'), 0)

    def test_reverse_cancels_debit(self):
        events = [
            debit('d1', 1, 'a', 50),
            reverse('r1', 2, 'a', 'd1'),
        ]
        self.assertEqual(balance(events, 'a'), 0)

    def test_reverse_ignored_when_other_account(self):
        events = [
            credit('c1', 1, 'b', 100),
            reverse('r1', 2, 'b', 'c1'),
        ]
        self.assertEqual(balance(events, 'a'), 0)

    def test_does_not_mutate_input(self):
        events = [
            credit('c1', 3, 'a', 100),
            debit('d1', 1, 'a', 30),
        ]
        before = [dict(e) for e in events]
        balance(events, 'a')
        self.assertEqual(events, before)


